<style scoped lang="scss" src="./button.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  ButtonMode,
  ButtonSize,
  ButtonState,
  ButtonModeValues,
  ButtonSizeValues,
  ButtonStateValues
} from "./button.constants";
import { has } from "../../util/has";
import Icon from "../../components/icon/icon.vue";
import { IconShape } from "../../components/icon/icon.constants";
import { MobileManager } from "../../util/mobile-manager";

/**
 * Simple labeled button
 */
@Component({
  components: {
    Icon
  }
})
export default class Button extends Vue {
  /** Render mode of the Button */
  @Prop({
    type: String,
    default: ButtonMode.PRIMARY,
    validator: has(ButtonModeValues)
  }) mode;

  /** Render size of the Button */
  @Prop({
    type: String,
    default: ButtonSize.LARGE,
    validator: has(ButtonSizeValues)
  }) size;

  /** Render size of the Button when the page is rendering for mobile */
  @Prop({
    type: String,
    validator: has(ButtonSizeValues)
  }) mobileSize;

  /** Forces a visual render state for the button */
  @Prop({
    type: String,
    validator: has(ButtonStateValues)
  }) forceState;

  /** Text label for the center of the button */
  @Prop({ type: String, default: "" }) label;

  /** Text label for the center of the button */
  @Prop({ type: String, default: "" }) mobileLabel;

  /** Icon Displayed inline with the label on the left */
  @Prop({ type: Number }) icon;

  @Prop({ type: Number }) iconSize;
  @Prop({ type: String }) iconColor;

  /** When true, the button will set it's width to fill it's container */
  @Prop({ type: Boolean, default: false }) stretch;

  /**
   * When true, the button will set it's width to fill it's container when in
   * mobile state
   */
  @Prop({ type: Boolean, default: false }) mobileStretch;

  /** Custom background CSS color for the button */
  @Prop({ type: String }) backgroundColor;

  /** Custom CSS color for the label */
  @Prop({ type: String }) labelColor;

  /** Internal tracked interaction state of the button */
  state = null;
  /** Mobile tracking flag used by the MobileManager */
  isMobile = false;

  ButtonState = ButtonState;

  get stateClass() { return (this.forceState || this.state) ? `${this.mode}${this.forceState || this.state}` : '' }
  get stretchClass() { return this.stretch || (this.mobileStretch && this.isMobile) ? "Button--stretch" : "" }

  get IconShape() {
    return IconShape;
  }

  get ButtonMode() {
    return ButtonMode;
  }

  get IconSize() {
    if (this.size === ButtonSize.SMALL) return 12;
    return 24;
  }

  get buttonStyle() {
    if (!this.backgroundColor) return {};

    return {
      background: this.backgroundColor
    }
  }

  get labelStyle() {
    if (!this.labelColor) return {};

    return {
      color: this.labelColor
    }
  }

  get text() {
    return this.isMobile ? (this.mobileLabel || this.label) : this.label;
  }

  beforeMount() {
    MobileManager.addListener(this);
  }

  beforeDestroy() {
    MobileManager.removeListener(this);
  }

  handleOver() {
    this.state = ButtonState.HOVER;
  }

  handleOut() {
    this.state = null;
  }

  handleActive() {
    this.state = ButtonState.ACTIVE;
  }

  handleBlur() {
    this.state = null;
  }
}
</script>

<template>
  <button
    tabindex="0"
    v-bind:class="[
      'Button',
      mode,
      isMobile ? mobileSize || size : size,
      stateClass,
      stretchClass,
    ]"
    :style="buttonStyle"
    :disabled="forceState === ButtonState.DISABLE"
    @mouseover="handleOver"
    @mouseout="handleOut"
    @focus="handleActive"
    @blur="handleBlur"
    @click="$emit('click')"
  >
    <div
      class="Button__Label"
      v-if="label || icon !== undefined || $slots.default"
    >
      <Icon
        v-if="icon"
        class="Button__Icon"
        :shape="icon"
        :size="iconSize || IconSize"
        :color="iconColor"
      />
      <span
        v-if="text || $slots.default"
        :style="labelStyle"
        :class="[
          'Button__Text',
          { 'Button__Text--WithIcon': icon !== undefined },
        ]"
      >
        <slot v-if="$slots.default" />
        <span v-else>
          {{ text }}
        </span>
      </span>
    </div>
  </button>
</template>
